  let cur: string[] | null = null;
  for (const line of lines) {
    if (/^##\s/.test(line)) {
      if (cur) sections.push(cur.join('\n'));
      cur = [line];
    } else if (cur) cur.push(line);
    else preamble.push(line);
  }
  if (cur) sections.push(cur.join('\n'));
  return { preamble: preamble.join('\n'), sections };
