export function matchesAgentQuery(agent: Agent, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return [agent.name, agent.project, repoLabelOf(agent), agent.cwd]
    .some((field) => (field ?? '').toLowerCase().includes(q));
}

