function candidatesFrom(markdown: string): string[] {
  const out: string[] = [];
  for (const line of markdown.split('\n')) {
    const heading = line.match(/^#{2,4}\s+(.+?)\s*$/);
    if (heading) out.push(stripDatePrefix(heading[1]));
