  if ((m = k.match(/^last(\d+)weeks?$/))) { const n = +m[1]; return { label: `Last ${n} weeks`, start: civ(Y, M, D - (n * 7 - 1)), end: civ(Y, M, D) }; }
  if ((m = k.match(/^last(\d+)months?$/))){ const n = +m[1]; return { label: `Last ${n} months`, start: civ(Y, M - n, D + 1), end: civ(Y, M, D) }; }
  return null;
}

