  const r = setSecret(ref, v);
  if (r.ok) return undefined;
  if (!warnedNoEncryption) {
    warnedNoEncryption = true;
    console.warn(`[config] ${r.error ?? 'secret store unavailable'} — secrets stay in config.json on this machine`);
