function ftsMatchTerms(query: string): string | null {
  const terms = String(query ?? '').match(/[\p{L}\p{N}_]+/gu);
  if (!terms || terms.length === 0) return null;
  return terms.slice(0, 32).map((t) => `"${t}"`).join(' ');
