function win32Components(p: string): string | null {
  if (process.platform !== 'win32') return p;
  const parts = p.split(/[\\/]/);
  for (let i = 0; i < parts.length; i++) {
    const c = parts[i];
    if (!c || c === '.' || c === '..') continue;
    const trimmed = c.replace(/[. ]+$/, '');
    if (!trimmed) return null; // e.g. `...` — main cannot say what it names
    parts[i] = trimmed;
  }
  return parts.join('\\');
}

