function stats(kgRoot) {
  const docs = list(kgRoot);
  let chunkCount = 0;
  const byModality = Object.create(null);
  for (const d of docs) {
    chunkCount += d.chunkCount || 0;
    byModality[d.modality] = (byModality[d.modality] || 0) + 1;
  }
  return { docCount: docs.length, chunkCount, byModality };
}

