  const sig = cryptoSign('sha256', Buffer.from(signingInput, 'utf8'), {
    key: vapidPrivateKeyObject(keys),
    dsaEncoding: 'ieee-p1363'
  });
  return `vapid t=${signingInput}.${toB64Url(sig)}, k=${keys.publicKey}`;
}

