  const { updateAgent, pushFeed } = useStore.getState();

  if (agent.status === 'blocked') {
    // Wait for user action; don't move automatically.
    return;
  }

  // Decision based on current status
  if (agent.status === 'idle') {
    // Maybe start a new task
