export function tokensInWindow(rec: AccountPoolRecord | undefined, now: number): number {
  if (!rec) return 0;
  let sum = 0;
  for (const [ts, tok] of rec.usage) if (ts >= now - USAGE_WINDOW_MS) sum += tok;
  return sum;
}

