function platformGuardNames(src) {
  const names = new Set(['process.platform']);
  const re = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*[^;\n]*process\.platform[^;\n]*/g;
  let m;
  while ((m = re.exec(src))) names.add(m[1]);
  return [...names];
}

