    for (let gx = 0; gx <= grid.gw; gx++) {
      const c = at.get(gy * grid.gw + gx);
      const key = c ? c.join(',') : null;
      if (key !== (cur ? cur.join(',') : null)) { flush(gx); if (c) { start = gx; cur = c; } else cur = null; }
    }
    flush(grid.gw);
  }
