  entries: ReadonlyArray<PooledTerminal>,
  cap = TERMINAL_POOL_MAX,
  keep?: string
): string[] {
  const over = entries.length - cap;
  if (over <= 0) return [];
  return entries
    .filter((e) => !e.attached && e.ptyId !== keep)
    .sort((a, b) => a.lastUsedAt - b.lastUsedAt)
    .slice(0, over)
    .map((e) => e.ptyId);
}

